changeSet.sql:
INSERT INTO parser (name, description, dataset_name, list_type, website_url, plugin_id, plugin_url, data_source_type, parser_kind, source_location, parameters, refresh_hours, retention_months, licence, attribution, notes, enabled, created_at) VALUES ('PEP Espagne – Nominations et cessations du BOE', 'Nominations, désignations, promotions et cessations publiées au BOE (section II.A) : Gouvernement, secrétaires d''État, hauts cargos, hautes juridictions, ambassadeurs et officiers généraux, avec les dates de fin (blocs ES-a, ES-c, ES-d, ES-e, ES-f)', 'es_pep_boe', 'PEP', 'https://www.boe.es', 'es-pep-boe', 'D:/test parser 2/plugins/swiftcheck-aml-es-pep-boe-0.0.1-SNAPSHOT.jar', 'PLUGIN_MANAGED', 'OFFICIAL_GAZETTE', NULL, '{"archiveMonths":"26","sections":"2A","delayMs":"250","monthsAfterEnd":"24"}', 24, 24, 'Réutilisation autorisée en citant la source (Agencia Estatal Boletín Oficial del Estado)', 'Agencia Estatal Boletín Oficial del Estado, www.boe.es (datos abiertos)', 'API de données ouvertes du BOE : un sommaire par jour. Les titres des décrets royaux (« se nombra… a don X », « se dispone el cese de don X como… ») donnent la personne, la fonction et la date ; le décret qui nomme tous les ministres est lu dans son texte. Les fonctions retenues sont dans boe-functions.json (dans le plugin). Premier passage : environ 800 jours à lire (quelques minutes), puis seulement les nouveaux jours.', TRUE, NOW());
INSERT INTO pep_function_parser (function_id, parser_id, completeness, includes_former, covered_scope, gaps) SELECT f.id, p.id, 'PARTIAL', TRUE, 'Le décret de nomination et de cessation du Président du Gouvernement.', 'Seuls les changements publiés au BOE depuis le début de l''archive (26 mois) : un titulaire en fonction depuis avant n''y figure pas et doit venir d''un parser d''institution.' FROM pep_function f JOIN pep_category c ON c.id = f.category_id, parser p WHERE c.code = 'ES-a' AND f.label LIKE 'Président du Gouvernement%' AND p.dataset_name = 'es_pep_boe';
INSERT INTO pep_function_parser (function_id, parser_id, completeness, includes_former, covered_scope, gaps) SELECT f.id, p.id, 'PARTIAL', TRUE, 'Les décrets de nomination et de cessation des vice-présidents.', 'Seuls les changements publiés au BOE depuis le début de l''archive (26 mois) : un titulaire en fonction depuis avant n''y figure pas et doit venir d''un parser d''institution.' FROM pep_function f JOIN pep_category c ON c.id = f.category_id, parser p WHERE c.code = 'ES-a' AND f.label LIKE 'Vice-président du Gouvernement%' AND p.dataset_name = 'es_pep_boe';
