INSERT INTO pep_function_parser (function_id, parser_id, completeness, includes_former, covered_scope, gaps) SELECT f.id, p.id, 'PARTIAL', TRUE, 'Les décrets de nomination et de cessation des sous-secrétaires.', 'Seuls les changements publiés au BOE depuis le début de l''archive (26 mois) : un titulaire en fonction depuis avant n''y figure pas et doit venir d''un parser d''institution.' FROM pep_function f JOIN pep_category c ON c.id = f.category_id, parser p WHERE c.code = 'ES-a' AND f.label LIKE 'Sous-secrétaire%' AND p.dataset_name = 'es_pep_boe';
INSERT INTO pep_function_parser (function_id, parser_id, completeness, includes_former, covered_scope, gaps) SELECT f.id, p.id, 'PARTIAL', TRUE, 'Les cessations publiées au BOE, avec leur date.', 'Seuls les changements publiés au BOE depuis le début de l''archive (26 mois) : un titulaire en fonction depuis avant n''y figure pas et doit venir d''un parser d''institution.' FROM pep_function f JOIN pep_category c ON c.id = f.category_id, parser p WHERE c.code = 'ES-a' AND f.label LIKE 'Ancien membre du Gouvernement%' AND p.dataset_name = 'es_pep_boe';
INSERT INTO pep_function_parser (function_id, parser_id, completeness, includes_former, covered_scope, gaps) SELECT f.id, p.id, 'PARTIAL', TRUE, 'Les nominations de magistrats et présidents du Tribunal constitutionnel publiées au BOE.', 'Seuls les changements publiés au BOE depuis le début de l''archive (26 mois) : un titulaire en fonction depuis avant n''y figure pas et doit venir d''un parser d''institution.' FROM pep_function f JOIN pep_category c ON c.id = f.category_id, parser p WHERE c.code = 'ES-c' AND f.label LIKE 'Magistrat du Tribunal constitutionnel%' AND p.dataset_name = 'es_pep_boe';
INSERT INTO pep_function_parser (function_id, parser_id, completeness, includes_former, covered_scope, gaps) SELECT f.id, p.id, 'PARTIAL', TRUE, 'Les nominations de magistrats et de présidents de chambre du Tribunal suprême.', 'Seuls les changements publiés au BOE depuis le début de l''archive (26 mois) : un titulaire en fonction depuis avant n''y figure pas et doit venir d''un parser d''institution.' FROM pep_function f JOIN pep_category c ON c.id = f.category_id, parser p WHERE c.code = 'ES-c' AND f.label LIKE 'Magistrat ou président de chambre du Tribunal suprême%' AND p.dataset_name = 'es_pep_boe';
INSERT INTO pep_function_parser (function_id, parser_id, completeness, includes_former, covered_scope, gaps) SELECT f.id, p.id, 'PARTIAL', TRUE, 'Les nominations de membres et de dirigeants du CGPJ publiées au BOE.', 'Seuls les changements publiés au BOE depuis le début de l''archive (26 mois) : un titulaire en fonction depuis avant n''y figure pas et doit venir d''un parser d''institution.' FROM pep_function f JOIN pep_category c ON c.id = f.category_id, parser p WHERE c.code = 'ES-c' AND f.label LIKE 'Membre du Conseil général du pouvoir judiciaire%' AND p.dataset_name = 'es_pep_boe';
INSERT INTO pep_function_parser (function_id, parser_id, completeness, includes_former, covered_scope, gaps) SELECT f.id, p.id, 'PARTIAL', TRUE, 'Les nominations de présidents de l''Audiencia Nacional et des tribunaux supérieurs de justice.', 'Seuls les changements publiés au BOE depuis le début de l''archive (26 mois) : un titulaire en fonction depuis avant n''y figure pas et doit venir d''un parser d''institution.' FROM pep_function f JOIN pep_category c ON c.id = f.category_id, parser p WHERE c.code = 'ES-c' AND f.label LIKE 'Président de l''Audiencia Nacional ou d''un tribunal supérieur de justice%' AND p.dataset_name = 'es_pep_boe';
INSERT INTO pep_function_parser (function_id, parser_id, completeness, includes_former, covered_scope, gaps) SELECT f.id, p.id, 'PARTIAL', TRUE, 'Fiscal General del Estado, fiscales de Sala, fiscales superiores et fiscales jefes anticorruption et antidrogue.', 'Seuls les changements publiés au BOE depuis le début de l''archive (26 mois) : un titulaire en fonction depuis avant n''y figure pas et doit venir d''un parser d''institution.' FROM pep_function f JOIN pep_category c ON c.id = f.category_id, parser p WHERE c.code = 'ES-c' AND f.label LIKE 'Procureur général de l''État et procureurs en chef%' AND p.dataset_name = 'es_pep_boe';
INSERT INTO pep_function_parser (function_id, parser_id, completeness, includes_former, covered_scope, gaps) SELECT f.id, p.id, 'PARTIAL', TRUE, 'Les nominations de président et de conseillers du Tribunal de Cuentas.', 'Seuls les changements publiés au BOE depuis le début de l''archive (26 mois) : un titulaire en fonction depuis avant n''y figure pas et doit venir d''un parser d''institution.' FROM pep_function f JOIN pep_category c ON c.id = f.category_id, parser p WHERE c.code = 'ES-d' AND f.label LIKE 'Président ou conseiller du Tribunal de Cuentas%' AND p.dataset_name = 'es_pep_boe';
INSERT INTO pep_function_parser (function_id, parser_id, completeness, includes_former, covered_scope, gaps) SELECT f.id, p.id, 'PARTIAL', TRUE, 'Les désignations d''ambassadeurs et de représentants permanents (« se designa Embajador de España en… »).', 'Seuls les changements publiés au BOE depuis le début de l''archive (26 mois) : un titulaire en fonction depuis avant n''y figure pas et doit venir d''un parser d''institution.' FROM pep_function f JOIN pep_category c ON c.id = f.category_id, parser p WHERE c.code = 'ES-e' AND f.label LIKE 'Ambassadeur ou chef de mission%' AND p.dataset_name = 'es_pep_boe';
INSERT INTO pep_function_parser (function_id, parser_id, completeness, includes_former, covered_scope, gaps) SELECT f.id, p.id, 'PARTIAL', TRUE, 'Les promotions aux grades de général de division et au-dessus, amiraux et chefs d''état-major.', 'Seuls les changements publiés au BOE depuis le début de l''archive (26 mois) : un titulaire en fonction depuis avant n''y figure pas et doit venir d''un parser d''institution.' FROM pep_function f JOIN pep_category c ON c.id = f.category_id, parser p WHERE c.code = 'ES-e' AND f.label LIKE 'Chef d''état-major ou officier général%' AND p.dataset_name = 'es_pep_boe';
INSERT INTO pep_function_parser (function_id, parser_id, completeness, includes_former, covered_scope, gaps) SELECT f.id, p.id, 'PARTIAL', TRUE, 'Les nominations et cessations des directeurs généraux.', 'Seuls les changements publiés au BOE depuis le début de l''archive (26 mois) : un titulaire en fonction depuis avant n''y figure pas et doit venir d''un parser d''institution.' FROM pep_function f JOIN pep_category c ON c.id = f.category_id, parser p WHERE c.code = 'ES-f' AND f.label LIKE 'Directeur général et assimilés%' AND p.dataset_name = 'es_pep_boe';
