INSERT INTO pep_function_parser (function_id, parser_id, completeness, includes_former, covered_scope, gaps) SELECT f.id, p.id, 'PARTIAL', TRUE, 'Les nominations et cessations des secrétaires généraux.', 'Seuls les changements publiés au BOE depuis le début de l''archive (26 mois) : un titulaire en fonction depuis avant n''y figure pas et doit venir d''un parser d''institution.' FROM pep_function f JOIN pep_category c ON c.id = f.category_id, parser p WHERE c.code = 'ES-f' AND f.label LIKE 'Secrétaire général de l''administration%' AND p.dataset_name = 'es_pep_boe';
INSERT INTO pep_function_parser (function_id, parser_id, completeness, includes_former, covered_scope, gaps) SELECT f.id, p.id, 'PARTIAL', TRUE, 'Les nominations aux organismes listés dans boe-functions.json (CNMV, CNMC, CSN, AEPD…).', 'Seuls les changements publiés au BOE depuis le début de l''archive (26 mois) : un titulaire en fonction depuis avant n''y figure pas et doit venir d''un parser d''institution.' FROM pep_function f JOIN pep_category c ON c.id = f.category_id, parser p WHERE c.code = 'ES-f' AND f.label LIKE 'Président ou membre du conseil d''un organisme régulateur%' AND p.dataset_name = 'es_pep_boe';

INSERT INTO parser (name, description, dataset_name, list_type, website_url, plugin_id, plugin_url, data_source_type, parser_kind, source_location, parameters, refresh_hours, retention_months, licence, attribution, notes, enabled, created_at) VALUES ('PEP Espagne – Députés du Congreso', 'Les députés du Congreso de los Diputados en fonction et les anciens sortis depuis moins de 24 mois, d''après l''open data du Congreso (bloc ES-b)', 'es_pep_congreso', 'PEP', 'https://www.congreso.es/es/opendata/diputados', 'es-pep-congreso', 'D:/test parser 2/plugins/swiftcheck-aml-es-pep-congreso-0.0.1-SNAPSHOT.jar', 'PLUGIN_MANAGED', 'OPEN_DATA_FILE', NULL, '{"pageUrl":"https://www.congreso.es/es/opendata/diputados","monthsAfterEnd":"24"}', 24, 24, 'Réutilisation autorisée en citant la source (Congreso de los Diputados, open data)', 'Congreso de los Diputados, www.congreso.es', 'Deux fichiers JSON dont le nom change à chaque mise à jour (DiputadosActivos et DiputadosDeBaja), trouvés par la page de l''open data. Ni date de naissance ni identifiant dans la source ; la biographie n''est pas reprise.', TRUE, NOW());
INSERT INTO pep_function_parser (function_id, parser_id, completeness, includes_former, covered_scope, gaps) SELECT f.id, p.id, 'COMPLETE', TRUE, 'Députés en fonction et sortis depuis moins de 24 mois, avec circonscription, groupe parlementaire, formation électorale et dates de mandat.', 'Pas de date de naissance dans l''open data : le rapprochement se fait sur le nom.' FROM pep_function f JOIN pep_category c ON c.id = f.category_id, parser p WHERE c.code = 'ES-b' AND f.label LIKE 'Député au Congreso%' AND p.dataset_name = 'es_pep_congreso';
INSERT INTO pep_function_parser (function_id, parser_id, completeness, includes_former, covered_scope, gaps) SELECT f.id, p.id, 'PARTIAL', TRUE, 'Les députés du Congreso sortis depuis moins de 24 mois.', 'Les sénateurs sortis ne sont pas couverts avant le parser du Sénat.' FROM pep_function f JOIN pep_category c ON c.id = f.category_id, parser p WHERE c.code = 'ES-b' AND f.label LIKE 'Ancien parlementaire national%' AND p.dataset_name = 'es_pep_congreso';
